    @Throws(ParseException::class)
    private fun jj_consume_token(kind: Int): Token {
        val oldToken: Token
        if ((token.also { oldToken = it }).next != null) token = token.next
        else {
            token.next = token_source.getNextToken()
            token = token.next
        }
        jj_ntk = -1
        if (token.kind == kind) {
            jj_gen++
            if (++jj_gc > 100) {
                jj_gc = 0
                for (i in jj_2_rtns.indices) {
                    var c = jj_2_rtns[i]
                    while (c != null) {
                        if (c.gen < jj_gen) c.first = null
                        c = c.next
                    }
                }
            }
            return token
        }
        token = oldToken
        jj_kind = kind
        throw generateParseException()
    }

    private class LookaheadSuccess : Error()

    private val jj_ls = LookaheadSuccess()
    private fun jj_scan_token(kind: Int): Boolean {
        if (jj_scanpos === jj_lastpos) {
            jj_la--
            if (jj_scanpos!!.next == null) {
                jj_scanpos!!.next = token_source.getNextToken()
                jj_scanpos = jj_scanpos!!.next
                jj_lastpos = jj_scanpos
            } else {
                jj_scanpos = jj_scanpos!!.next
                jj_lastpos = jj_scanpos
            }
        } else {
            jj_scanpos = jj_scanpos!!.next
        }
        if (jj_rescan) {
            var i = 0
            var tok = token
            while (tok != null && tok !== jj_scanpos) {
                i++
                tok = tok.next
            }
            if (tok != null) jj_add_error_token(kind, i)
        }
        if (jj_scanpos!!.kind != kind) return true
        if (jj_la == 0 && jj_scanpos === jj_lastpos) throw jj_ls
        return false
    }


    val nextToken: Token
        /** Get the next Token.  */
        get() {
            if (token.next != null) token = token.next
            else {
                token.next = token_source.getNextToken()
                token = token.next
            }
            jj_ntk = -1
            jj_gen++
            return token
        }

    /** Get the specific Token.  */
    fun getToken(index: Int): Token {
        var t = token
        for (i in 0..<index) {
            if (t.next != null) t = t.next
            else {
                t.next = token_source.getNextToken()
                t = t.next
            }
        }
        return t
    }

    private fun jj_ntk(): Int {
        if ((token.next.also { jj_nt = it }) == null) return ((token_source.getNextToken()
            .also { token.next = it }).kind.also { jj_ntk = it })
        else return (jj_nt!!.kind.also { jj_ntk = it })
    }

    private val jj_expentries: MutableList<*> = ArrayList<Any?>()
    private var jj_expentry: IntArray
    private var jj_kind = -1
    private val jj_lasttokens = IntArray(100)
    private var jj_endpos = 0

    private fun jj_add_error_token(kind: Int, pos: Int) {
        if (pos >= 100) return
        if (pos == jj_endpos + 1) {
            jj_lasttokens[jj_endpos++] = kind
        } else if (jj_endpos != 0) {
            jj_expentry = IntArray(jj_endpos)
            for (i in 0..<jj_endpos) {
                jj_expentry[i] = jj_lasttokens[i]
            }
            var it = jj_expentries.iterator()
            jj_entries_loop@ while (it.hasNext()) {
                val oldentry = (it.next()) as IntArray
                if (oldentry.size == jj_expentry.size) {
                    for (i in jj_expentry.indices) {
                        if (oldentry[i] != jj_expentry[i]) {
                            continue@jj_entries_loop
                        }
                    }
                    jj_expentries.add(jj_expentry)
                    break@jj_entries_loop
                }
            }
            if (pos != 0) jj_lasttokens[(pos.also { jj_endpos = it }) - 1] = kind
        }
    }

    /** Generate ParseException.  */
    fun generateParseException(): ParseException {
        jj_expentries.clear()
        val la1tokens = BooleanArray(95)
        if (jj_kind >= 0) {
            la1tokens[jj_kind] = true
            jj_kind = -1
        }
        for (i in 0..33) {
            if (jj_la1[i] == jj_gen) {
                for (j in 0..31) {
                    if ((jj_la1_0[i] and (1 shl j)) != 0) {
                        la1tokens[j] = true
                    }
                    if ((jj_la1_1[i] and (1 shl j)) != 0) {
                        la1tokens[32 + j] = true
                    }
                    if ((jj_la1_2[i] and (1 shl j)) != 0) {
                        la1tokens[64 + j] = true
                    }
                }
            }
        }
        for (i in 0..94) {
            if (la1tokens[i]) {
                jj_expentry = IntArray(1)
                jj_expentry[0] = i
                jj_expentries.add(jj_expentry)
            }
        }
        jj_endpos = 0
        jj_rescan_token()
        jj_add_error_token(0, 0)
        val exptokseq = arrayOfNulls<IntArray>(jj_expentries.size)
        for (i in jj_expentries.indices) {
            exptokseq[i] = jj_expentries.get(i) as IntArray?
        }
        return ParseException(token, exptokseq, LuaParserConstants.Companion.tokenImage)
    }

